UPDATE memories SET payload = '{"id": "ashley-dangerous-carnival", "character_ko": "애슐리 테일러", "character_ja": "アシュリー・テイラー", "name_ko": "데인저러스 그로귀여움 카니발", "name_ja": "デンジャラスグロかわカーニバル", "rarity": 5, "role": "버퍼", "element": "무속성", "limited": true, "stats": {"HP": 10726, "공격력": 3522, "방어력": 3910, "스피드": 122}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/ashley-dangerous-carnival-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HRvUgyWbkAAJ5sH.jpeg). 공식 게시물 URL과 게시일은 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["기억·스킬 고유명사의 한국어 표기는 임시 번역입니다.", "스킬·한계돌파 효과는 공식 이미지의 최대 강화 수치 기준입니다.", "이미지에 소모 SP나 브레이크 감소량이 없는 스킬은 해당 값을 추정하지 않았습니다.", "グロかわ는 그로테스크함과 귀여움을 결합한 표현으로, 기억 이름을 임시로 그로귀여움으로 옮겼습니다.", "추가 치명타 피해의 차지 조건 판정 시점은 이미지 문장 순서대로 보존했으며 게임 내 확인이 필요합니다."], "pending": [], "skills": [{"kind": "필살기", "name_ja": "デンジャラスグロかわカーニバル", "name_ko": "데인저러스 그로귀여움 카니발", "ja": "敵全体に300%の無属性ダメージを与える。\n味方全体の弱点属性に対して与えるダメージ+25%(2ターン)。\n付与対象が無属性のとき、さらに弱点属性に対して与えるダメージ+15%(2ターン)。\n自身のチャージ+10%。\nさらに【チャージが100%のとき】\n味方全体のクリティカルダメージ+40%(2ターン)。\n付与対象が無属性のとき、さらにクリティカルダメージ+30%(2ターン)。\n自身のチャージ-50%", "ko": "적 전체에게 300%의 무속성 피해를 준다.\n아군 전체의 약점 속성에 대해 주는 피해 +25%(2턴).\n부여 대상이 무속성이면 추가로 약점 속성에 대해 주는 피해 +15%(2턴).\n자신의 차지 +10%.\n추가로 【차지가 100%일 때】\n아군 전체의 치명타 피해 +40%(2턴).\n부여 대상이 무속성이면 추가로 치명타 피해 +30%(2턴).\n자신의 차지 -50%.", "cost": "MP 75", "break": 25}, {"kind": "전투 스킬", "name_ja": "ポップンチアフルスマイル", "name_ko": "팝픈 치어풀 스마일", "ja": "味方全体にクリティカル率+30%(2ターン)、攻撃力+30%(2ターン)。\n無属性の味方全体にプラッシーチア(2ターン)を付与する。\n自身のチャージ+10%。", "ko": "아군 전체에게 치명타 확률 +30%(2턴), 공격력 +30%(2턴).\n무속성 아군 전체에게 플러시 치어(2턴)를 부여한다.\n자신의 차지 +10%.", "cost": null, "break": null}, {"kind": "전투 스킬 · 고유 효과", "name_ja": "プラッシーチア", "name_ko": "플러시 치어", "ja": "クリティカル率+10%、弱点属性に対して与えるダメージ+10%。\n付与対象の攻撃でクリティカルが発生したとき、MP+5。\n※通常攻撃/戦闘スキル/必殺技のみ有効", "ko": "치명타 확률 +10%, 약점 속성에 대해 주는 피해 +10%.\n부여 대상의 공격에서 치명타가 발생하면 MP +5.\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.", "cost": null, "break": null}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の無属性ダメージを与える。\n自身のチャージ+5%", "ko": "적 하나에게 100%의 무속성 피해를 준다.\n자신의 차지 +5%.", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "ヘイスト", "name_ko": "헤이스트", "ja": "バトル開始時にチャージ0%(最大100%)、味方全体のスピード+10%。\n自身以外の味方の攻撃でクリティカルが発生したとき、自身のチャージ+10%。\nさらにその攻撃で無属性ダメージを与えたとき、自身のチャージ+5%。\n※通常攻撃/戦闘スキル/必殺技のみ有効。\n【自身のチャージが10%以上のとき】\n自身のスピード+3%(チャージが10%増えるごとに効果が上昇、最大15%)", "ko": "전투 시작 시 차지 0%(최대 100%), 아군 전체의 스피드 +10%.\n자신 이외의 아군 공격에서 치명타가 발생하면 자신의 차지 +10%.\n추가로 그 공격이 무속성 피해를 주면 자신의 차지 +5%.\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.\n【자신의 차지가 10% 이상일 때】\n자신의 스피드 +3%(차지가 10% 증가할 때마다 효과 증가, 최대 15%).", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "シャープエンチャント", "name_ko": "샤프 인챈트", "ja": "【バッファーに装備時】\n味方全体のクリティカル率+5%。\n自身が必殺技を発動したとき、味方全体に弱点属性に対して与えるダメージ+15%(2ターン)", "ko": "【버퍼에게 장착 시】\n아군 전체의 치명타 확률 +5%.\n자신이 필살기를 발동하면 아군 전체에게 약점 속성에 대해 주는 피해 +15%(2턴).", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "KAWAIIは私に力をくれマス！", "name_ko": "KAWAII는 제게 힘을 줍니DA!", "ja": "バトル開始時、自身のチャージ+50%。\nプラッシーチアが付与されている味方全体の受けるダメージ-10%", "ko": "전투 시작 시 자신의 차지 +50%.\n플러시 치어가 부여된 아군 전체가 받는 피해 -10%.", "cost": null, "break": null}], "limit_breaks": [{"stage": 1, "ja": "HP・攻撃力・防御力+2%\n付与するバフの効果ターン+1", "ko": "HP·공격력·방어력 +2%.\n부여하는 버프의 효과 지속 턴 +1."}, {"stage": 2, "ja": "HP・攻撃力・防御力+2%\n【チャージ100%のとき】\nスピード+10%\n【敵のブレイクボーナスが最大になったとき】\nMP+25%、チャージ+50%", "ko": "HP·공격력·방어력 +2%.\n【차지가 100%일 때】\n스피드 +10%.\n【적의 브레이크 보너스가 최대가 되었을 때】\nMP +25%, 차지 +50%."}, {"stage": 3, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}, {"stage": 4, "ja": "HP・攻撃力・防御力+2%\n付与するバフの効果+50%(※MP回復系/行動順上昇効果は除く)、必殺技を発動したときSP+1", "ko": "HP·공격력·방어력 +2%.\n부여하는 버프의 효과 +50%(※ MP 회복 계열 / 행동 순서 상승 효과 제외). 필살기를 발동하면 SP +1."}, {"stage": 5, "ja": "HP・攻撃力・防御力+2%\n必殺技Lv上限+3", "ko": "HP·공격력·방어력 +2%.\n필살기 레벨 상한 +3."}], "acquisition": "한정"}' WHERE id = 'ashley-dangerous-carnival';
UPDATE memories SET payload = '{"id": "homura-metal-conversion", "character_ko": "아케미 호무라", "character_ja": "暁美ほむら", "name_ko": "금속체로의 변환과 투척", "name_ja": "金属体への変換と投擲", "rarity": 5, "role": "어태커", "element": "불속성", "limited": true, "stats": {"HP": 9554, "공격력": 4553, "방어력": 3295, "스피드": 105}, "stats_note": "공식 이미지에 능력치의 레벨·돌파 조건이 명시되어 있지 않습니다.", "image": "/images/homura-metal-conversion-official.jpeg", "source_url": null, "source_note": "사용자가 제공한 공식 소개 이미지(HTSheKOasAAvLtf.jpeg). 공식 게시물 URL과 게시일은 확인 대기.", "verification": "전체 초벌 번역 · 고유명사와 효과 해석 검수 대기", "translation_notes": ["기억·스킬 고유명사의 한국어 표기는 임시 번역입니다.", "스킬·한계돌파 효과는 공식 이미지의 최대 강화 수치 기준입니다.", "이미지에 소모 SP나 브레이크 감소량이 없는 스킬은 해당 값을 추정하지 않았습니다.", "전투 스킬 두 형태에는 공통 브레이크 감소량 12를 적용했습니다.", "잔염의 깃털 보유 시 필살기 추가 효과의 판정 시점은 원문 조건을 보존했으며 실제 동작 확인이 필요합니다."], "pending": [], "skills": [{"kind": "필살기", "name_ja": "金属体への変換と投擲", "name_ko": "금속체로의 변환과 투척", "ja": "【必要BP15】\n敵全体に270%の火属性ダメージを与え、さらに5回ダメージを与える(1回ごとにランダムな敵単体に10%の火属性ダメージを与える)。\n自身に残焔の羽根を付与し、降り注ぐ金属体の与えるダメージ+50%(2ターン)。\nさらに【残焔の羽根が付与されているとき】\n必殺技発動時に自身のクリティカルダメージ+20%。\n自身が再行動し、BP+5。\n残焔の羽根を解除する", "ko": "【필요 BP 15】\n적 전체에게 270%의 불속성 피해를 주고, 추가로 5회 피해를 준다(1회마다 무작위 적 하나에게 10%의 불속성 피해).\n자신에게 잔염의 깃털을 부여하고, 쏟아지는 금속체가 주는 피해 +50%(2턴).\n추가로 【잔염의 깃털이 부여된 상태】\n필살기 발동 시 자신의 치명타 피해 +20%.\n자신이 재행동하고, BP +5.\n잔염의 깃털을 해제한다.", "cost": "MP 0", "break": 25}, {"kind": "필살기 · 고유 효과", "name_ja": "残焔の羽根", "name_ko": "잔염의 깃털", "ja": "スピード+10%。\n自身が敵から攻撃を受けたとき自身のBP+1。", "ko": "스피드 +10%.\n자신이 적에게 공격받으면 자신의 BP +1.", "cost": null, "break": null}, {"kind": "전투 스킬 · 일반 상태", "name_ja": "人形たちによる刺突", "name_ko": "인형들의 찌르기", "ja": "【通常時】\n敵全体に180%の火属性ダメージを与える。\n自身に弱点属性に対して与えるダメージ+30%(3ターン)。\n火属性フィールド(ストック+3)を発動する。", "ko": "【일반 상태】\n적 전체에게 180%의 불속성 피해를 준다.\n자신에게 약점 속성에 대해 주는 피해 +30%(3턴).\n불속성 필드(스톡 +3)를 발동한다.", "cost": null, "break": 12}, {"kind": "전투 스킬 · 필드 발동 중", "name_ja": "蜥蜴の召喚", "name_ko": "도마뱀 소환", "ja": "【自身の火属性フィールド発動中】\n敵全体に210%の火属性ダメージを与える。\n自身に弱点属性に対して与えるダメージ+30%(3ターン)、BP+1。\n攻撃対象に火属性から受けるダメージ+10%(3ターン)。\n火属性フィールドのストック+2。", "ko": "【자신의 불속성 필드 발동 중】\n적 전체에게 210%의 불속성 피해를 준다.\n자신에게 약점 속성에 대해 주는 피해 +30%(3턴), BP +1.\n공격 대상에게 불속성으로 받는 피해 +10%(3턴).\n불속성 필드의 스톡 +2.", "cost": null, "break": 12}, {"kind": "전투 스킬 · 필드", "name_ja": "火属性フィールド", "name_ko": "불속성 필드", "ja": "味方全体の火属性の与えるダメージ+30%、火属性のクリティカル率+30%。\nストックの最大値は3、発動者が通常攻撃を発動したときストック-1", "ko": "아군 전체의 불속성으로 주는 피해 +30%, 불속성 치명타 확률 +30%.\n스톡의 최대치는 3. 발동자가 일반 공격을 발동하면 스톡 -1.", "cost": null, "break": null}, {"kind": "일반 공격", "name_ja": "通常攻撃", "name_ko": "일반 공격", "ja": "敵単体に100%の火属性ダメージを与える。\nさらに【自身の火属性フィールド発動中】\n自身の受けるダメージ-10%(1ターン)", "ko": "적 하나에게 100%의 불속성 피해를 준다.\n추가로 【자신의 불속성 필드 발동 중】\n자신이 받는 피해 -10%(1턴).", "cost": null, "break": 10}, {"kind": "어빌리티", "name_ja": "アサルトヘイスト", "name_ko": "어설트 헤이스트", "ja": "自身のHPが50%以上のときスピード+15%。\n自身または味方が敵に火属性ダメージを与えたとき自身のスピード+2%(累積10回)、攻撃力+3%(累積10回)。\n※通常攻撃/戦闘スキル/必殺技のみ有効。\n自身以外の味方が通常攻撃で敵に火属性ダメージを与えたときBP+1。\n自身以外の味方が戦闘スキルで敵に火属性ダメージを与えたときBP+2。\n【敵がブレイクしたときまたは自身の火属性フィールド発動中に自身が必殺技を発動したとき】\n降り注ぐ金属体を発動する。", "ko": "자신의 HP가 50% 이상이면 스피드 +15%.\n자신 또는 아군이 적에게 불속성 피해를 주면 자신의 스피드 +2%(10회 중첩), 공격력 +3%(10회 중첩).\n※ 일반 공격 / 전투 스킬 / 필살기에만 유효.\n자신 이외의 아군이 일반 공격으로 적에게 불속성 피해를 주면 BP +1.\n자신 이외의 아군이 전투 스킬로 적에게 불속성 피해를 주면 BP +2.\n【적이 브레이크되었을 때 또는 자신의 불속성 필드 발동 중 자신이 필살기를 발동했을 때】\n쏟아지는 금속체를 발동한다.", "cost": null, "break": null}, {"kind": "어빌리티 · 추가 공격", "name_ja": "降り注ぐ金属体", "name_ko": "쏟아지는 금속체", "ja": "敵全体に80%の火属性ダメージを与える。\n自身の降り注ぐ金属体の与えるダメージ+5%(累積5回)", "ko": "적 전체에게 80%의 불속성 피해를 준다.\n자신의 쏟아지는 금속체가 주는 피해 +5%(5회 중첩).", "cost": null, "break": null}, {"kind": "서포트 어빌리티", "name_ja": "アサルトヘイスト", "name_ko": "어설트 헤이스트", "ja": "【アタッカーに装備時】\n攻撃力+10%、スピード+10%。\nHP50%以上のとき受けるダメージ-10%、戦闘スキルで与えるダメージ+10%", "ko": "【어태커에게 장착 시】\n공격력 +10%, 스피드 +10%.\nHP가 50% 이상이면 받는 피해 -10%, 전투 스킬로 주는 피해 +10%.", "cost": null, "break": null}, {"kind": "전용 EX 결정 어빌리티", "name_ja": "もう一度、会いたい", "name_ko": "다시 한번, 만나고 싶어", "ja": "スピード+10%、攻撃力+10%。\n【残焔の羽根が付与されているとき】\n必殺技発動時に自身の弱点属性に対して与えるダメージ+20%", "ko": "스피드 +10%, 공격력 +10%.\n【잔염의 깃털이 부여된 상